using System.IO.Compression;
using System.Reflection;
using System.Windows;
namespace KsrSetup;
public partial class App : Application { [STAThread] public static void Main(){var target=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"KSR Automation Browser");try{Directory.CreateDirectory(target);var resource=Assembly.GetExecutingAssembly().GetManifestResourceNames().Single(x=>x.EndsWith("Portable_x64.zip"));using var s=Assembly.GetExecutingAssembly().GetManifestResourceStream(resource)!;using var z=new ZipArchive(s);foreach(var e in z.Entries){var path=Path.GetFullPath(Path.Combine(target,e.FullName));if(!path.StartsWith(Path.GetFullPath(target)))continue;if(string.IsNullOrEmpty(e.Name)){Directory.CreateDirectory(path);continue;}Directory.CreateDirectory(Path.GetDirectoryName(path)!);e.ExtractToFile(path,true);}var shell=Type.GetTypeFromProgID("WScript.Shell");dynamic w=Activator.CreateInstance(shell!)!;dynamic l=w.CreateShortcut(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory),"KSR Automation Browser.lnk"));l.TargetPath=Path.Combine(target,"Launcher","KsrAutomationBrowser.Launcher.exe");l.WorkingDirectory=target;l.Save();System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo(l.TargetPath){UseShellExecute=true});MessageBox.Show("KSR Automation Browser was installed for the current user.","Installation complete");}catch(Exception e){MessageBox.Show(e.Message,"Installation failed",MessageBoxButton.OK,MessageBoxImage.Error);}}}
